def gini(values: List[float], weights: Optional[List[float]] = None) -> float:
    if not values:
        return 0.0
    if weights is None:
        weights = [1.0] * len(values)
    pairs = sorted(zip(values, weights), key=lambda vw: vw[0])
    W = sum(w for _, w in pairs)
    V = sum(v * w for v, w in pairs)
    if W == 0 or V == 0:
        return 0.0
    cumV = 0.0
    B = 0.0  # area under Lorenz curve
    for v, w in pairs:
        prev_cumV = cumV
        cumV += v * w
        B += (prev_cumV + cumV) * w / (2.0 * V)
    # Weighted Gini
    return max(0.0, min(1.0, 1.0 - 2.0 * B / (W / W)))

